#pragma once

#include <string>
#include <string_view>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <optional>
#include <cstdint>
#include <algorithm>
#include <nlohmann/json.hpp>

namespace ptv {

struct ProgNodeEffect {
    // Multipliers applied to construct systems; default 1.0 means no change
    float drain_mult{1.0f};
    float cooldown_mult{1.0f};
    float durability_mult{1.0f};
};

struct ProgNode {
    std::string id;                  // unique key (e.g., "attack_core", "defense_ii")
    std::string family;              // construct family or upgrade bucket this node targets
    int cost_xp{0};
    std::vector<std::string> prereq; // node ids
    ProgNodeEffect effects;          // multipliers this node contributes when unlocked
};

struct SoftCapRule {
    // For aggregate multipliers after combining all unlocked effects
    float min_val{0.5f};   // clamp low
    float max_val{2.0f};   // clamp high
    float k{0.0f};         // optional non-linear squeeze; 0 disables
};

struct ProgTree {
    // Indexed by node id
    std::unordered_map<std::string, ProgNode> nodes;
};

struct ProgressionState {
    // Currency
    int total_xp_earned{0};
    int unspent_xp{0};

    // Ownership
    std::unordered_set<std::string> unlocked_nodes;    // node ids
    std::unordered_set<std::string> enabled_families;  // family ids enabled via unlocks

    // Aggregated tuning per family after soft caps
    struct FamilyTuning { ProgNodeEffect eff; };
    std::unordered_map<std::string, FamilyTuning> tuning_by_family;

    // Loadout pins (construct ids)
    std::vector<std::string> pinned; // order matters; unique

    // Recent mission ids processed to avoid double-counting (best-effort)
    std::unordered_set<std::string> processed_event_ids;
};

// ------------ Parsing helpers -------------
inline ProgNodeEffect parse_effects(const nlohmann::json& j) {
    ProgNodeEffect e{};
    if (j.is_object()) {
        e.drain_mult = j.value("drain_mult", 1.0f);
        e.cooldown_mult = j.value("cooldown_mult", 1.0f);
        e.durability_mult = j.value("durability_mult", 1.0f);
    }
    return e;
}

inline ProgTree parse_unlock_tree(const nlohmann::json& j) {
    ProgTree t{};
    if (!j.is_object() || !j.contains("nodes") || !j.at("nodes").is_array()) return t;
    for (const auto& n : j.at("nodes")) {
        if (!n.is_object()) continue;
        ProgNode node{};
        node.id = n.value("id", std::string{});
        node.family = n.value("family", std::string{});
        node.cost_xp = n.value("cost_xp", 0);
        if (n.contains("prereq") && n.at("prereq").is_array()) {
            for (const auto& p : n.at("prereq")) node.prereq.push_back(p.get<std::string>());
        }
        if (n.contains("effects")) node.effects = parse_effects(n.at("effects"));
        if (!node.id.empty()) t.nodes[node.id] = std::move(node);
    }
    return t;
}

inline std::unordered_map<std::string, SoftCapRule> parse_soft_caps(const nlohmann::json& j) {
    std::unordered_map<std::string, SoftCapRule> m;
    if (!j.is_object()) return m;
    auto parse_one = [](const nlohmann::json& jj){
        SoftCapRule r; r.min_val = jj.value("min", 0.5f); r.max_val = jj.value("max", 2.0f); r.k = jj.value("k", 0.0f); return r; };
    if (j.contains("drain_mult")) m["drain_mult"] = parse_one(j.at("drain_mult"));
    if (j.contains("cooldown_mult")) m["cooldown_mult"] = parse_one(j.at("cooldown_mult"));
    if (j.contains("durability_mult")) m["durability_mult"] = parse_one(j.at("durability_mult"));
    return m;
}

// Combine two ProgNodeEffect multiplicatively
inline ProgNodeEffect combine(const ProgNodeEffect& a, const ProgNodeEffect& b) {
    ProgNodeEffect r{};
    r.drain_mult = a.drain_mult * b.drain_mult;
    r.cooldown_mult = a.cooldown_mult * b.cooldown_mult;
    r.durability_mult = a.durability_mult * b.durability_mult;
    return r;
}

inline float apply_soft_cap_scalar(float v, const SoftCapRule* rule) {
    if (!rule) return v;
    // Clamp first
    v = std::max(rule->min_val, std::min(rule->max_val, v));
    if (rule->k <= 0.0f) return v;
    // Smooth squeeze around 1.0 using a gentle non-linear mapping
    // y = 1 + (v-1) / (1 + k * |v-1|)
    float d = v - 1.0f; float ad = std::abs(d);
    float y = 1.0f + d / (1.0f + rule->k * ad);
    // Re-clamp to bounds
    y = std::max(rule->min_val, std::min(rule->max_val, y));
    return y;
}

inline ProgNodeEffect apply_soft_caps_effect(const ProgNodeEffect& e, const std::unordered_map<std::string, SoftCapRule>& rules) {
    ProgNodeEffect r = e;
    auto it = rules.find("drain_mult"); r.drain_mult = apply_soft_cap_scalar(r.drain_mult, it==rules.end()?nullptr:&it->second);
    it = rules.find("cooldown_mult"); r.cooldown_mult = apply_soft_cap_scalar(r.cooldown_mult, it==rules.end()?nullptr:&it->second);
    it = rules.find("durability_mult"); r.durability_mult = apply_soft_cap_scalar(r.durability_mult, it==rules.end()?nullptr:&it->second);
    return r;
}

// Utility: ensure unique push to vector
inline void push_unique(std::vector<std::string>& v, const std::string& s, std::size_t max_keep) {
    if (s.empty()) return;
    v.erase(std::remove(v.begin(), v.end(), s), v.end());
    v.insert(v.begin(), s);
    if (v.size() > max_keep) v.resize(max_keep);
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <entt/entt.hpp>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>
#include <algorithm>

#include "progression_shared.h"

namespace ptv {

static bool has_all_prereq(const ProgressionState& s, const ProgNode& n) {
    for (const auto& p : n.prereq) if (!s.unlocked_nodes.count(p)) return false;
    return true;
}

static void aggregate_family_effects(const ProgTree& tree,
                                     const ProgressionState& s,
                                     const std::unordered_map<std::string, SoftCapRule>& caps,
                                     std::unordered_map<std::string, ProgressionState::FamilyTuning>& out) {
    out.clear();
    // Start with identity effects per family for any unlocked nodes
    for (const auto& node_id : s.unlocked_nodes) {
        auto it = tree.nodes.find(node_id);
        if (it == tree.nodes.end()) continue;
        const ProgNode& n = it->second;
        auto& fam = out[n.family];
        fam.eff = combine(fam.eff, n.effects);
    }
    // Apply caps
    for (auto& kv : out) {
        kv.second.eff = apply_soft_caps_effect(kv.second.eff, caps);
    }
}

// Emit enable + tuning tags for a family when first unlocked or when tuning changes
static void publish_construct_enable(World& w, std::uint32_t e, const std::string& family) {
    std::string s = std::string("construct.enable:") + nlohmann::json({{"family", family}}).dump();
    if (w.has<CTag>(e)) {
        auto& tags = w.get<CTag>(e).tags; tags.push_back(s);
    } else {
        CTag t; t.tags.push_back(s); w.emplace_or_replace<CTag>(e, std::move(t));
    }
}

static void publish_construct_tuning(World& w, std::uint32_t e, const std::string& family, const ProgNodeEffect& eff) {
    nlohmann::json j{{"family", family}, {"drain_mult", eff.drain_mult}, {"cooldown_mult", eff.cooldown_mult}, {"durability_mult", eff.durability_mult}};
    std::string s = std::string("construct.tuning:") + j.dump();
    if (w.has<CTag>(e)) { auto& tags = w.get<CTag>(e).tags; tags.push_back(s);} else { CTag t; t.tags.push_back(s); w.emplace_or_replace<CTag>(e, std::move(t)); }
}

// Public helper for other compilation units in this task
void progression_recompute_and_publish(World& w, std::uint32_t e,
                                       const ProgTree& tree,
                                       const std::unordered_map<std::string, SoftCapRule>& caps,
                                       ProgressionState& st) {
    // Families enabled are those with at least one unlocked node that defines a family id.
    std::unordered_set<std::string> newly_enabled;

    // Re-aggregate tuning
    aggregate_family_effects(tree, st, caps, st.tuning_by_family);

    // Scan through nodes for any families to enable
    for (const auto& node_id : st.unlocked_nodes) {
        auto it = tree.nodes.find(node_id); if (it == tree.nodes.end()) continue;
        const std::string& fam = it->second.family;
        if (fam.empty()) continue;
        if (!st.enabled_families.count(fam)) {
            st.enabled_families.insert(fam);
            newly_enabled.insert(fam);
        }
    }

    // Publish events
    for (const auto& fam : newly_enabled) publish_construct_enable(w, e, fam);
    for (const auto& kv : st.tuning_by_family) publish_construct_tuning(w, e, kv.first, kv.second.eff);
}

bool progression_try_spend(World& w, std::uint32_t e,
                           const ProgTree& tree,
                           const std::unordered_map<std::string, SoftCapRule>& caps,
                           ProgressionState& st,
                           const std::string& node_id,
                           std::string* failure_reason_out) {
    auto it = tree.nodes.find(node_id);
    if (it == tree.nodes.end()) { if (failure_reason_out) *failure_reason_out = "unknown_node"; return false; }
    const ProgNode& n = it->second;
    if (st.unlocked_nodes.count(node_id)) { if (failure_reason_out) *failure_reason_out = "already_unlocked"; return false; }
    if (st.unspent_xp < n.cost_xp) { if (failure_reason_out) *failure_reason_out = "not_enough_xp"; return false; }
    if (!has_all_prereq(st, n)) { if (failure_reason_out) *failure_reason_out = "missing_prereq"; return false; }

    st.unspent_xp -= n.cost_xp;
    st.unlocked_nodes.insert(node_id);

    // Toast + re-aggregate + publish
    {
        nlohmann::json toast{{"text", std::string("Unlocked: ")+node_id}, {"ttl", 2.0}};
        std::string s = std::string("ui.toast:") + toast.dump();
        if (w.has<CTag>(e)) { auto& tags = w.get<CTag>(e).tags; tags.push_back(s);} else { CTag t; t.tags.push_back(s); w.emplace_or_replace<CTag>(e, std::move(t)); }
    }

    progression_recompute_and_publish(w, e, tree, caps, st);
    return true;
}

void progression_publish_pins(World& w, std::uint32_t e, const std::vector<std::string>& pins) {
    nlohmann::json j{{"pinned", pins}};
    std::string s = std::string("construct.pinned:") + j.dump();
    if (w.has<CTag>(e)) { auto& tags = w.get<CTag>(e).tags; tags.push_back(s);} else { CTag t; t.tags.push_back(s); w.emplace_or_replace<CTag>(e, std::move(t)); }
}

} // namespace ptv

